def objs(g):
    from collections import deque
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and (ny,nx) not in seen and g[ny][nx]==c:
                                seen.add((ny,nx)); q.append((ny,nx))
                ys=[c0[0] for c0 in cells]; xs=[c0[1] for c0 in cells]
                out.append((c,min(ys),min(xs),sorted([(y-min(ys),x-min(xs)) for y,x in cells])))
    return out
